{
  "name": "CareLens",
  "description": "A 3D preventive care application featuring an AI-driven prevention dashboard, symptom analysis, and personalized management plans."
}

export interface UserProfile {
  name: string;
  age: string;
  gender: string;
  email: string;
  location: string;
  conditions: string;
  allergies: string;
  medications: string;
  familyHistory: string;
  organDonor: boolean;
  diet: string;
  activity: string; // Type, duration, frequency
  sleep: string;
  substanceUse: string;
}

export interface Symptom {
  id: string;
  name: string;
  severity: number; // 1-10
  duration: string;
  date: string;
  notes: string;
}

export interface Vaccination {
  id: string;
  name: string;
  date: string;
  notes: string;
}

export interface Screening {
  id: string;
  name: string;
  date: string;
  result: string;
  nextDueDate?: string;
}

export interface HealthMetric {
  date: string;
  systolic: number;
  diastolic: number;
  heartRate: number;
  weight: number;
}

export enum ViewState {
  HOME = 'HOME',
  PROFILE = 'PROFILE',
  PREVENTION = 'PREVENTION',
  ANALYSIS = 'ANALYSIS',
  MANAGEMENT = 'MANAGEMENT',
}

import { GoogleGenAI } from "@google/genai";
import { UserProfile, Symptom } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Using gemini-3-flash-preview for quicker responses, pro for deep reasoning
const MODEL_FLASH = 'gemini-3-flash-preview';
const MODEL_PRO = 'gemini-3-pro-preview';

export const getGeminiRecommendations = async (
  profile: UserProfile,
  context: 'vaccine' | 'screening' | 'lifestyle'
): Promise<string> => {
  const prompt = `
    Based on the following user profile, provide personalized recommendations for ${context}.

    User Profile:
    - Age: ${profile.age}
    - Gender: ${profile.gender}
    - Location: ${profile.location}
    - Medical History: ${profile.conditions}, ${profile.familyHistory}
    - Lifestyle: ${profile.activity}, ${profile.diet}, ${profile.substanceUse}

    Context Specific Instructions:
    ${context === 'vaccine' ? 'Suggest necessary immunizations, boosters, and explain why based on location/demographics.' : ''}
    ${context === 'screening' ? 'Suggest preventive screenings (cancer, cardio, etc) relevant to age/gender/risk and frequency.' : ''}
    ${context === 'lifestyle' ? 'Suggest evidence-based avoidant measures and lifestyle habits to reduce health risks.' : ''}

    Keep the tone professional yet caring. Format with clear bullet points.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_FLASH,
      contents: prompt,
    });
    return response.text || "Unable to generate recommendations at this time.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error connecting to AI service. Please try again later.";
  }
};

export const analyzeSymptomsAndRisks = async (
  profile: UserProfile,
  symptoms: Symptom[]
): Promise<string> => {
  const symptomText = symptoms.map(s => `${s.name} (Severity: ${s.severity}/10, Duration: ${s.duration})`).join(', ');

  const prompt = `
    Act as an advanced medical AI assistant named CareLens. 
    Analyze the following user profile and symptom diary.

    User Profile:
    - Age: ${profile.age}, Gender: ${profile.gender}
    - History: ${profile.conditions}, ${profile.familyHistory}

    Current Symptoms:
    ${symptomText}

    Task:
    1. Provide a "Risk Analysis" based on the symptoms and history.
    2. Suggest "Smart Tests & Screenings" that should be considered to diagnose the issue. Explain WHAT the test is, HOW it is done, and WHY it is necessary.
    3. Suggest immediate personalized measures to manage symptoms.

    DISCLAIMER: Start with a strong disclaimer that you are an AI and this is not medical advice.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_PRO, // Using Pro for better reasoning capabilities
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 2048 } // Allow some thinking for risk assessment
      }
    });
    return response.text || "Unable to analyze risks.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error connecting to AI service.";
  }
};

export const getManagementPlan = async (
  profile: UserProfile,
  condition: string
): Promise<string> => {
  const prompt = `
    Create a Disease-Specific Management Plan for a user with: ${condition}.

    User Context:
    - Age: ${profile.age}
    - Current Habits: ${profile.activity}, ${profile.diet}

    Include:
    1. Educational Module: Explain the condition briefly and emerging info.
    2. Habits to Adopt: Personalized actions (e.g., specific exercises, dietary changes).
    3. Rationale: Why these changes help manage ${condition}.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_FLASH,
      contents: prompt,
    });
    return response.text || "Unable to generate plan.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error connecting to AI service.";
  }
};

import React from 'react';

interface CrystalNodeProps {
  icon: string;
  label: string;
  colorClass: string; // Tailwind class for text color
  glowClass: string; // CSS animation class
  gradientClass: string; // Tailwind gradient bg
  onClick: () => void;
  delay?: string;
}

const CrystalNode: React.FC<CrystalNodeProps> = ({ icon, label, colorClass, glowClass, gradientClass, onClick, delay = '0s' }) => {
  return (
    <div 
      className="group relative flex flex-col items-center justify-center cursor-pointer animate-float"
      style={{ animationDelay: delay }}
      onClick={onClick}
    >
      {/* Glow Effect behind */}
      <div className={`absolute inset-0 rounded-full blur-xl opacity-0 group-hover:opacity-60 transition-opacity duration-500 ${colorClass.replace('text-', 'bg-')}`}></div>

      {/* The Crystal Shape */}
      <div 
        className={`relative w-24 h-24 md:w-32 md:h-32 flex items-center justify-center crystal-shape transition-all duration-300 transform group-hover:scale-110 ${gradientClass}`}
        style={{ animation: `${glowClass} 3s infinite` }}
      >
        <div className="absolute inset-1 bg-black bg-opacity-40 crystal-shape flex items-center justify-center backdrop-blur-sm">
           <span className="text-4xl md:text-5xl filter drop-shadow-lg">{icon}</span>
        </div>
      </div>

      {/* Label (appears on hover) */}
      <div className={`mt-4 opacity-0 group-hover:opacity-100 transition-opacity duration-300 font-bold text-lg tracking-wider ${colorClass} bg-black/60 px-3 py-1 rounded-full backdrop-blur-md border border-white/10`}>
        {label}
      </div>
    </div>
  );
};

export default CrystalNode;

