              <div className="absolute top-0 right-0 p-4 opacity-10">
                 <Shield size={120} />
              </div>

              <h3 className="text-xl font-bold text-white mb-2 flex items-center gap-2">
                 <Sparkles className="text-yellow-400 animate-pulse" /> 
                 AI Recommendations
              </h3>
              <p className="text-sm text-blue-200 mb-6">
                Based on your profile ({userProfile.age}yo {userProfile.gender} in {userProfile.location}), here is your personalized 
                {activeTab === 'vaccines' ? ' immunization plan.' : activeTab === 'screening' ? ' screening schedule.' : ' lifestyle guide.'}
              </p>

              <div className="flex-1 overflow-y-auto bg-black/30 rounded-lg p-4 font-light text-gray-200 border border-white/5 shadow-inner">
                {loading ? (
                   <div className="flex items-center justify-center h-full space-x-2">
                      <div className="w-3 h-3 bg-blue-400 rounded-full animate-bounce"></div>
                      <div className="w-3 h-3 bg-blue-400 rounded-full animate-bounce delay-100"></div>
                      <div className="w-3 h-3 bg-blue-400 rounded-full animate-bounce delay-200"></div>
                   </div>
