      setBgOffset({ x, y });
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  const closeModal = () => setView(ViewState.HOME);

  // Generate background crystals with specified palettes
  const backgroundCrystals = useMemo(() => {
    return Array.from({ length: 30 }).map((_, i) => {
      const typeSeed = Math.random();
      let type = 'crystal-shape';
      if (typeSeed > 0.6) type = 'crystal-shard';
      if (typeSeed > 0.8) type = 'crystal-spire';

      // 0: Sapphire Blue to Ultraviolet (#2D5BFF to #8C52FF)
      // 1: Amethyst Purple to Magenta (#9D46FF to #FF0099)
      // 2: Emerald Green to Teal (#00FF94 to #00BCD4)
      const palette = i % 3;
      let gradient = '';
      if (palette === 0) gradient = 'from-[#2D5BFF] to-[#8C52FF]';
      else if (palette === 1) gradient = 'from-[#9D46FF] to-[#FF0099]';
      else gradient = 'from-[#00FF94] to-[#00BCD4]';

      return {
        id: i,
        left: `${Math.random() * 100}%`,
        top: `${Math.random() * 100}%`,
        size: `${Math.random() * 150 + 50}px`,
        rotation: Math.random() * 360,
        gradient,
        type,
        opacity: Math.random() * 0.15 + 0.05,
        duration: Math.random() * 20 + 10,
        delay: Math.random() * 5
      };
    });
  }, []);

  return (
    <div className="relative w-full h-screen overflow-hidden bg-[#121212]">

      {/* 3D Abstract Background */}
      <div 
        className="absolute inset-0 pointer-events-none perspective-3d"
        style={{ transform: `translate(${bgOffset.x * 0.5}px, ${bgOffset.y * 0.5}px)` }}
