        {backgroundCrystals.map((crystal) => (
          <div
            key={crystal.id}
            className={`absolute ${crystal.type} bg-gradient-to-br ${crystal.gradient} backdrop-blur-sm animate-float-deep`}
            style={{
              left: crystal.left,
              top: crystal.top,
              width: crystal.size,
              height: crystal.size,
              opacity: crystal.opacity,
              transform: `rotate(${crystal.rotation}deg)`,
              animationDuration: `${crystal.duration}s`,
              animationDelay: `${crystal.delay}s`,
            }}
          />
        ))}

        {/* Lighting overlays */}
        <div className="absolute top-1/4 left-1/4 w-[600px] h-[600px] bg-[#2D5BFF] rounded-full blur-[150px] opacity-10 mix-blend-screen animate-pulse"></div>
        <div className="absolute bottom-1/4 right-1/4 w-[500px] h-[500px] bg-[#FF0099] rounded-full blur-[150px] opacity-10 mix-blend-screen animate-pulse" style={{animationDelay: '2s'}}></div>
      </div>

      {/* Main Home Content */}
      <div className={`relative z-10 w-full h-full flex flex-col items-center justify-center transition-all duration-500 ${view !== ViewState.HOME ? 'opacity-20 pointer-events-none scale-95 blur-sm' : 'opacity-100 scale-100 blur-0'}`}>

        <div className="flex flex-col items-center mb-16 md:mb-24">
           <h1 className="text-5xl md:text-7xl font-bold tracking-[0.2em] text-transparent bg-clip-text bg-gradient-to-r from-[#00FF94] via-[#2D5BFF] to-[#FF0099] drop-shadow-[0_0_15px_rgba(45,91,255,0.5)] uppercase">
            CareLens
          </h1>
          <p className="text-cyan-200/50 tracking-widest mt-2 uppercase text-sm">Preventive Care Ecosystem</p>
        </div>

        {/* Horizontal Shard Layout */}
        <div className="flex flex-col md:flex-row items-center justify-center gap-8 md:gap-16 w-full max-w-7xl px-4">

          {/* 1. User Profile - Cyan Glow (retained style, positioned first) */}
          <CrystalNode 
            icon="👤" 
            label="User Profile" 
            colorClass="text-cyan-400" 
            glowClass="animate-[pulse-glow-cyan_4s_infinite]"
            gradientClass="bg-gradient-to-br from-cyan-400/20 to-blue-600/20 border-2 border-cyan-400/50"
            onClick={() => setView(ViewState.PROFILE)}
          />

          {/* 2. Prevention Dashboard - Sapphire to UV */}
          <CrystalNode 
            icon="🛡️" 
            label="Prevention" 
            colorClass="text-indigo-300"
            glowClass="animate-[pulse-glow-blue_5s_infinite]"
            gradientClass="bg-gradient-to-br from-[#2D5BFF]/30 to-[#8C52FF]/30 border-2 border-[#2D5BFF]/50"
            onClick={() => setView(ViewState.PREVENTION)}
            delay="0.5s"
          />

          {/* 3. Management & Care - Emerald to Teal */}
          <CrystalNode 
            icon="🪴" 
            label="Management" 
            colorClass="text-teal-300"
            glowClass="animate-[pulse-glow-green_7s_infinite]"
            gradientClass="bg-gradient-to-br from-[#00FF94]/30 to-[#00BCD4]/30 border-2 border-[#00FF94]/50"
            onClick={() => setView(ViewState.MANAGEMENT)}
            delay="1s"
          />

          {/* 4. Analysis & Risk - Amethyst to Magenta */}
          <CrystalNode 
            icon="💎" 
            label="Analysis & Risk" 
            colorClass="text-fuchsia-300"
            glowClass="animate-[pulse-glow-purple_6s_infinite]"
            gradientClass="bg-gradient-to-br from-[#9D46FF]/30 to-[#FF0099]/30 border-2 border-[#9D46FF]/50"
            onClick={() => setView(ViewState.ANALYSIS)}
            delay="1.5s"
          />

        </div>
      </div>

      {/* Modals for Pages */}
      {view === ViewState.PROFILE && (
        <GlassModal title="User Profile" onClose={closeModal} borderColorClass="border-cyan-400/50 shadow-cyan-500/20">
          <UserProfileComponent data={userProfile} onChange={setUserProfile} />
        </GlassModal>
      )}

      {view === ViewState.PREVENTION && (
        <GlassModal title="Prevention Dashboard" onClose={closeModal} borderColorClass="border-[#2D5BFF]/50 shadow-indigo-500/20">
          <PreventionDashboard userProfile={userProfile} />
        </GlassModal>
      )}

      {view === ViewState.ANALYSIS && (
        <GlassModal title="Analysis & Risk" onClose={closeModal} borderColorClass="border-[#9D46FF]/50 shadow-fuchsia-500/20">
          <AnalysisRisk userProfile={userProfile} />
        </GlassModal>
      )}

      {view === ViewState.MANAGEMENT && (
        <GlassModal title="Management & Care" onClose={closeModal} borderColorClass="border-[#00FF94]/50 shadow-teal-500/20">
          <ManagementCare userProfile={userProfile} />
        </GlassModal>
      )}

    </div>
  );
};

export default App;

