  const crystals = [];

  const crystalCount = 10;
  const maxOpacity = 0.9;
  const minOpacity = 0.5;
  const maxScale = 1.3;
  const minScale = 0.5;

  for (let i = 0; i < crystalCount; i++) {
    const randomOpacity = Math.random() * (maxOpacity - minOpacity) + minOpacity;
    const randomScale = Math.random() * (maxScale - minScale) + minScale;
    const randomX = Math.random() * 100;
    const randomY = Math.random() * 100;
    const randomRotation = Math.random() * 360;

    const crystalStyle = {
      opacity: randomOpacity,
      transform: `scale(${randomScale}) rotate(${randomRotation}deg)`,
      left: `${randomX}%`,
      top: `${randomY}%`,
    };

    crystals.push(
      <div key={i} className="crystal" style={crystalStyle}></div>
    );
