                 <LineChart data={healthData}>
                   <CartesianGrid strokeDasharray="3 3" stroke="#333" />
                   <XAxis dataKey="date" stroke="#666" fontSize={12} />
                   <YAxis stroke="#666" fontSize={12} domain={[60, 160]} />
